export const activateSignatureRequest = defineFunction({
  name: "yousign.activate_signature_request",
  connector: "yousign",
  class: "sensitive",
  act: true,
  description: "Activate a draft signature request: Yousign emails every signer (and approver) an invitation to sign, and the request becomes ongoing (or approval). It cannot be undone here. The request needs at least one document and, for each signer, a signature field. Returns the request; signature links are not returned.",
  schema: {
    "type": "object",
    "additionalProperties": false,
    "required": ["signature_request_id"],
    "properties": {"signature_request_id": {"type": "string", "format": "uuid", "description": "Signature request id."}}
  },
  examples: [
    { title: "Send a prepared request", input: {"signature_request_id": "9b6ed2f3-244f-487a-baa1-bbe4f51c8748"} },
  ],
  refusals: [
    { code: "signature_request_not_found", when: 404, message: "No signature request with this id in this Yousign environment." },
    { code: "activation_refused", when: 400, message: "Yousign refused the activation: the request is not a draft, or lacks a document, a signer or a signer's signature field." },
  ],
  request: {
    method: "POST",
    path: "/signature_requests/{signature_request_id}/activate",
    pathParams: ["signature_request_id"],
    query: {},
    body: {},
    headers: {},
  },
  output: { strip: ["signers", "approvers"] },
  confirm: { summary: "Send signature request {signature_request_id}: Yousign emails every signer an invitation to sign; it cannot be undone here." },
})

export const connector = defineConnector({
  name: "yousign",
  label: "Yousign",
  namespace: "yousign",
  version: "1.1.1",
  apiVersion: "v3",
  baseUrls: {"setting": "environment", "values": {"production": "https://api.yousign.app/v3", "sandbox": "https://api-sandbox.yousign.app/v3"}},
  auth: {"kind": "bearer", "token": "api_key"},
  credential: [{"name": "api_key", "label": "API key", "secret": true, "holder": "account"}],
  settings: [{"name": "environment", "label": "Environment", "type": "choice", "choices": ["production", "sandbox"]}],
  modes: ["byo_org"],
  timeoutMs: 60000,
  queryArrays: "comma",
  rateLimit: { requests: 30, intervalMs: 60000 },
  errors: [
    { status: 400, code: "invalid_request", message: "Yousign rejected the request as invalid: its detail names the faulty field.", retryable: false },
    { status: 401, code: "access_rejected", message: "Yousign rejected the API key: unknown, revoked, or issued for the other environment (sandbox and production keys differ).", retryable: false, marksAccount: "credential_rejected" },
    { status: 403, code: "forbidden", message: "Yousign forbids this action in this context: the key's workspace scope, or the request's status, does not allow it.", retryable: false },
    { status: 404, code: "not_found", message: "Yousign object not found: check the id and the environment.", retryable: false },
    { status: 429, code: "rate_limited", message: "Yousign rate limit reached (per minute and per hour): retry later.", retryable: true },
    { status: [500, 502, 503, 504], code: "upstream_unavailable", message: "Yousign is temporarily unavailable or under maintenance: retry later.", retryable: true },
  ],
  probe: { function: "yousign.list_templates", nonEmpty: [] },
  exposure: {"mode": "per_connector", "tool": "yousign"},
  functions: [
    listSignatureRequests,
    getSignatureRequest,
    listTemplates,
    getTemplate,
    createSignatureRequestFromTemplate,
    createSignatureRequest,
    addDocument,
    addSigner,
    addField,
    listFields,
    updateField,
    deleteField,
    activateSignatureRequest,
  ],
})
